import{_ as i,o as s,c as t,a5 as e}from"./chunks/framework.BEZBAInb.js";const k=JSON.parse('{"title":"安装","description":"","frontmatter":{"title":"安装","order":1},"headers":[],"relativePath":"zh/latest/dotnet/installation.md","filePath":"zh/latest/dotnet/installation.md","lastUpdated":1788455378000}'),o={name:"zh/latest/dotnet/installation.md"};function n(l,a,d,h,p,r){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h1><h2 id="基础依赖" tabindex="-1">基础依赖 <a class="header-anchor" href="#基础依赖" aria-label="Permalink to &quot;基础依赖&quot;">​</a></h2><ol><li>安装 Konado 插件（必须）</li><li>支持 C# 的 Godot .NET 4.7.1 或更高版本</li><li>项目需要使用 Godot .NET 编辑器打开，普通 Godot 编辑器无法编译和加载 C# 插件脚本。</li></ol><h2 id="安装步骤" tabindex="-1">安装步骤 <a class="header-anchor" href="#安装步骤" aria-label="Permalink to &quot;安装步骤&quot;">​</a></h2><ol><li>将 konado_dotnet 插件解压缩到 Godot 项目的 <code>addons</code> 目录下</li><li>确认 <code>addons/konado</code> 主插件也在项目中</li><li>在 Godot 编辑器中，进入 <code>项目 -&gt; 项目设置 -&gt; 插件</code>，先启用 <code>Konado</code></li><li>构建 C# 项目，确保 MSBuild 没有报错</li><li>再启用 <code>Konado.NET</code> 插件</li><li>重新打开项目，让自动加载节点和 C# 脚本状态刷新</li></ol><h2 id="首次启用时的常见报错" tabindex="-1">首次启用时的常见报错 <a class="header-anchor" href="#首次启用时的常见报错" aria-label="Permalink to &quot;首次启用时的常见报错&quot;">​</a></h2><p>首次启用 Konado.NET 时，如果项目还没有完成 C# 构建，可能出现类似错误：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Unable to load addon script from path: &#39;res://addons/konado_dotnet/editor/KonadoDotNetPlugin.cs&#39;.</span></span></code></pre></div><p>这通常不是 Konado 主插件问题。请先在 Godot .NET 编辑器中构建项目，再重新打开项目并启用插件。</p><h2 id="启用顺序" tabindex="-1">启用顺序 <a class="header-anchor" href="#启用顺序" aria-label="Permalink to &quot;启用顺序&quot;">​</a></h2><p>Konado.NET 依赖 Konado 主插件。推荐顺序是：</p><ol><li>启用 <code>Konado</code></li><li>构建 C# 项目</li><li>启用 <code>Konado.NET</code></li></ol><p>如果先启用了 Konado.NET，插件会检查主插件状态；主插件未启用时，Konado.NET 不会继续注册 API 自动加载节点。</p><h2 id="场景要求" tabindex="-1">场景要求 <a class="header-anchor" href="#场景要求" aria-label="Permalink to &quot;场景要求&quot;">​</a></h2><p>使用 <code>DialogueManagerApi</code> 时，场景树中需要包含满足完整公开 API 契约的 <code>KonadoDialogueManager</code> 节点。Konado.NET 会在节点进入场景树时自动绑定，不依赖节点名称。</p><p>如果场景中存在多个对话管理器，请在 C# 中手动绑定：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Godot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> manager</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> GetNode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Node</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;UI/KonadoDialogueManager&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Konado.Runtime.Api.KonadoApi.DialogueManagerApi</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BindDialogueManager</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(manager);</span></span></code></pre></div>`,17)])])}const g=i(o,[["render",n]]);export{k as __pageData,g as default};
